inline void speciesProbabilities(const float* x,float* out) {
  float hidden0[64];
  for(uint16_t h=0;h<64;++h) { float value=kSpeciesBias0[h];
    for(uint16_t j=0;j<68;++j) value+=kSpeciesWeights0[h][j]*x[j];
    hidden0[h]=fmaxf(0.f,value); }
  for(uint16_t h=0;h<20;++h) { float value=kSpeciesBias1[h];
    for(uint16_t j=0;j<64;++j) value+=kSpeciesWeights1[h][j]*hidden0[j];
    out[h]=value; }
  float maximum=out[0];
  for(uint8_t c=1;c<kSpeciesCount;++c) maximum=fmaxf(maximum,out[c]);
  float total=0.f;
  for(uint8_t c=0;c<kSpeciesCount;++c) { out[c]=expf((out[c]-maximum)/kSpeciesTemperature);total+=out[c]; }
  for(uint8_t c=0;c<kSpeciesCount;++c) out[c]/=total;
}
inline int8_t bestSpecies(const float* p) {
  int8_t best=0;for(uint8_t c=1;c<kSpeciesCount;++c) if(p[c]>p[best]) best=c;return best; }
